import './Header.css';
import React from 'react';

function Header() {
  return (
    <div className="Header">
      <h1>Rein Urmet</h1>
      <p>Software Engineer</p>
      <p>Estonia, Tartu</p>
      <a href="../CV_Rein_Urmet.pdf" download class="download-btn">Download My CV</a>
    </div>
  );
}

export default Header;
